import{_ as e,o as a,c as i,a4 as t}from"./chunks/framework.vNSRaLQv.js";const k=JSON.parse('{"title":"Moonlight 自研源码分析","description":"","frontmatter":{"title":"Moonlight 自研源码分析","date":"2026-06-27T00:00:00.000Z"},"headers":[],"relativePath":"posts/Moonlight自研源码分析.md","filePath":"posts/Moonlight自研源码分析.md"}'),n={name:"posts/Moonlight自研源码分析.md"};function l(p,s,o,r,c,d){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="moonlight-自研源码分析" tabindex="-1">Moonlight 自研源码分析 <a class="header-anchor" href="#moonlight-自研源码分析" aria-label="Permalink to &quot;Moonlight 自研源码分析&quot;">​</a></h1><blockquote><p>时间：2026-06-27 目标：不是继续把上游当黑盒，而是拆清楚哪些层可以自己造、哪些层必须分阶段替换。</p></blockquote><hr><h2 id="_1-当前源码真实结构" tabindex="-1">1. 当前源码真实结构 <a class="header-anchor" href="#_1-当前源码真实结构" aria-label="Permalink to &quot;1. 当前源码真实结构&quot;">​</a></h2><p><code>moonlight-web-stream</code> 不是一个单体程序，而是三层：</p><table tabindex="0"><thead><tr><th>层</th><th>位置</th><th>作用</th><th>自研难度</th></tr></thead><tbody><tr><td>web-server</td><td><code>src/</code></td><td>账户、配置、HTTP API、Web UI、启动 streamer</td><td>低</td></tr><tr><td>common</td><td><code>common/</code></td><td>API 类型、配置、stdin/stdout IPC</td><td>低</td></tr><tr><td>streamer</td><td><code>streamer/</code></td><td>串流核心：Moonlight 协议、WebRTC/WebSocket transport、输入转发、音视频转发</td><td>高</td></tr><tr><td>moonlight-common-rust</td><td>cargo git dependency</td><td>配对、host HTTP API、RTSP/ENet/RTP/FEC、C bridge</td><td>最高</td></tr><tr><td>moonlight-common-c</td><td>dependency submodule</td><td>Limelight C 实现，真正成熟的 Moonlight streaming core</td><td>最高</td></tr></tbody></table><p>结论：如果要“自己造”，不能从 UI 或 web-server 开始冒充重写。真正的核心在 <code>streamer</code> 和 <code>moonlight-common-rust/moonlight-common-c</code>。</p><hr><h2 id="_2-web-server-做了什么" tabindex="-1">2. web-server 做了什么 <a class="header-anchor" href="#_2-web-server-做了什么" aria-label="Permalink to &quot;2. web-server 做了什么&quot;">​</a></h2><p>入口：<code>src/main.rs</code></p><p>web-server 负责：</p><ul><li>读取配置</li><li>初始化日志</li><li>启动 Actix HTTP/HTTPS 服务</li><li>挂载 API 和前端静态资源</li><li>在 <code>/host/stream</code> WebSocket 收到用户请求时启动 streamer 子进程</li></ul><p>关键文件：<code>src/api/stream.rs</code></p><p>流程：</p><ol><li>浏览器连接 <code>/host/stream</code></li><li>第一条 WebSocket 消息必须是 <code>StreamClientMessage::Init</code></li><li>web-server 根据用户、host、app 查配置和配对证书</li><li><code>Command::new(config.streamer_path)</code> 启动 <code>streamer.exe</code></li><li>web-server 和 streamer 之间通过 stdin/stdout 传 JSON line</li><li>浏览器 WebSocket 文本/二进制消息被转发给 streamer</li><li>streamer 返回的文本/二进制消息再转发给浏览器</li></ol><p>这层本质是“控制壳 + 子进程管理 + IPC 转发”。它不是串流核心。</p><p>自研策略：可以直接重写成 HomeSense 内部 TypeScript/Rust service，但第一阶段没有必要。</p><hr><h2 id="_3-ipc-协议" tabindex="-1">3. IPC 协议 <a class="header-anchor" href="#_3-ipc-协议" aria-label="Permalink to &quot;3. IPC 协议&quot;">​</a></h2><p>位置：<code>common/src/ipc.rs</code></p><p>IPC 非常简单：</p><ul><li>stdin/stdout</li><li>每条消息是一行 JSON</li><li>stderr 用于日志</li></ul><p>主要消息：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>ServerIpcMessage::Init</span></span>
<span class="line"><span>ServerIpcMessage::WebSocket(StreamClientMessage)</span></span>
<span class="line"><span>ServerIpcMessage::WebSocketTransport(Bytes)</span></span>
<span class="line"><span>ServerIpcMessage::Stop</span></span>
<span class="line"><span></span></span>
<span class="line"><span>StreamerIpcMessage::WebSocket(StreamServerMessage)</span></span>
<span class="line"><span>StreamerIpcMessage::WebSocketTransport(Bytes)</span></span>
<span class="line"><span>StreamerIpcMessage::Stop</span></span></code></pre></div><p>这意味着我们可以先“自己造 streamer”，但保持同一套 IPC，这样 web-server 和前端暂时不用大改。</p><p>这是最好的第一刀。</p><hr><h2 id="_4-streamer-做了什么" tabindex="-1">4. streamer 做了什么 <a class="header-anchor" href="#_4-streamer-做了什么" aria-label="Permalink to &quot;4. streamer 做了什么&quot;">​</a></h2><p>入口：<code>streamer/src/main.rs</code></p><p>启动流程：</p><ol><li>通过 stdin/stdout 建立 IPC</li><li>等待 <code>ServerIpcMessage::Init</code></li><li>用配对证书构造 <code>MoonlightHost</code></li><li>加载 WebRTC ICE server</li><li>等浏览器选择 transport：<code>WebRTC</code> 或 <code>WebSocket</code></li><li>收到 <code>StartStream</code> 后构造 <code>MoonlightStreamSettings</code></li><li>调用 <code>host.start_stream(...)</code></li><li>调用 <code>moonlight_instance.start_connection(...)</code></li><li>Moonlight C/Rust core 回调 video/audio/input/status</li><li>streamer 把 video/audio 包转成 WebRTC track 或 WebSocket binary 给浏览器</li></ol><p>核心结构：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>StreamConnection</span></span>
<span class="line"><span>  MoonlightHost</span></span>
<span class="line"><span>  MoonlightInstance</span></span>
<span class="line"><span>  MoonlightStream</span></span>
<span class="line"><span>  transport_sender</span></span>
<span class="line"><span>  StreamVideoDecoder</span></span>
<span class="line"><span>  StreamAudioDecoder</span></span>
<span class="line"><span>  StreamConnectionListener</span></span></code></pre></div><p>注意：<code>StreamVideoDecoder</code> 并不真正解码视频。它接收 host 发来的 compressed decode unit，然后交给 transport，最终由浏览器解码。</p><p>所以这个项目的 streamer 更准确叫：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Moonlight protocol bridge -&gt; browser transport bridge</span></span></code></pre></div><p>不是传统意义的本地解码播放器。</p><hr><h2 id="_5-transport-层" tabindex="-1">5. transport 层 <a class="header-anchor" href="#_5-transport-层" aria-label="Permalink to &quot;5. transport 层&quot;">​</a></h2><p>位置：</p><ul><li><code>streamer/src/transport/mod.rs</code></li><li><code>streamer/src/transport/webrtc/</code></li><li><code>streamer/src/transport/web_socket/</code></li><li><code>web/stream/transport/</code></li></ul><p>通道划分通过 <code>TransportChannelId</code>：</p><ul><li><code>HOST_VIDEO</code></li><li><code>HOST_AUDIO</code></li><li><code>GENERAL</code></li><li><code>STATS</code></li><li>鼠标、键盘、手柄、触摸、RTT 等输入通道</li></ul><p>浏览器端：</p><ul><li>WebRTC 模式：视频/音频走 MediaStreamTrack，输入和控制走 DataChannel</li><li>WebSocket 模式：音视频和输入都走 WebSocket binary</li></ul><p>streamer 端：</p><ul><li>收到浏览器输入包后调用 <code>MoonlightStream</code> 的输入 API</li><li>收到 Moonlight video/audio 回调后调用 transport 的 <code>send_video_unit</code> / <code>send_audio_sample</code></li></ul><p>自研时 transport 可以保留，先换 Moonlight core。</p><hr><h2 id="_6-真正最难的是-moonlight-common" tabindex="-1">6. 真正最难的是 moonlight-common <a class="header-anchor" href="#_6-真正最难的是-moonlight-common" aria-label="Permalink to &quot;6. 真正最难的是 moonlight-common&quot;">​</a></h2><p>当前 workspace 依赖：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;">moonlight-common</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> =</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> {</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;"> git</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> =</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;"> &quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">...moonlight-common-rust...</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;"> features</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> =</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> [</span></span>
<span class="line"><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">  &quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">tokio</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span></span>
<span class="line"><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">  &quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">tokio-hyper</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span></span>
<span class="line"><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">  &quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">openssl</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span></span>
<span class="line"><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">  &quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">stream-c</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span></span>
<span class="line"><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">  &quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">serde</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">]</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> }</span></span></code></pre></div><p>其中 <code>stream-c</code> 会引入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>moonlight-common-sys</span></span>
<span class="line"><span>  moonlight-common-c</span></span>
<span class="line"><span>    Connection.c</span></span>
<span class="line"><span>    ControlStream.c</span></span>
<span class="line"><span>    InputStream.c</span></span>
<span class="line"><span>    AudioStream.c</span></span>
<span class="line"><span>    VideoStream.c</span></span>
<span class="line"><span>    VideoDepacketizer.c</span></span>
<span class="line"><span>    RtspConnection.c</span></span>
<span class="line"><span>    PlatformCrypto.c</span></span>
<span class="line"><span>    ...</span></span></code></pre></div><p>也就是说：</p><ul><li>Rust 层负责高级 API、HTTP、类型包装</li><li>C 层负责成熟串流连接、RTSP、RTP/UDP、ENet、FEC、输入、音视频包处理</li></ul><p>如果要彻底自己造，最终要替掉 <code>moonlight-common-c</code>。</p><p>但第一阶段不应该直接重写全部 C core。应该先造一个兼容壳，逐步替换模块。</p><hr><h2 id="_7-自研路线判断" tabindex="-1">7. 自研路线判断 <a class="header-anchor" href="#_7-自研路线判断" aria-label="Permalink to &quot;7. 自研路线判断&quot;">​</a></h2><p>不建议路线：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>直接从零写完整 Moonlight 客户端</span></span></code></pre></div><p>原因：</p><ul><li>配对流程涉及证书、PIN、加密握手</li><li>启动流程涉及 Sunshine/NVIDIA GameStream HTTP API</li><li>streaming 涉及 RTSP、UDP/RTP、FEC、重传、控制通道</li><li>音视频需要正确 packetize/depacketize</li><li>输入注入协议复杂</li><li>WebRTC 再转发又是一层复杂度</li></ul><p>推荐路线：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>先自己造 streamer 壳，再逐步替换 moonlight-common</span></span></code></pre></div><hr><h2 id="_8-第一阶段-造自己的-streamer" tabindex="-1">8. 第一阶段：造自己的 streamer <a class="header-anchor" href="#_8-第一阶段-造自己的-streamer" aria-label="Permalink to &quot;8. 第一阶段：造自己的 streamer&quot;">​</a></h2><p>目标：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>homesense-streamer</span></span></code></pre></div><p>要求：</p><ul><li>保持现有 IPC 协议兼容</li><li>保持前端 WebSocket/WebRTC 协议兼容</li><li>暂时仍调用 moonlight-common-rust</li><li>把当前 streamer 的大文件拆成清晰模块</li></ul><p>建议结构：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>crates/homesense-streamer/</span></span>
<span class="line"><span>  src/main.rs</span></span>
<span class="line"><span>  src/ipc_bridge.rs</span></span>
<span class="line"><span>  src/session.rs</span></span>
<span class="line"><span>  src/moonlight/</span></span>
<span class="line"><span>    mod.rs</span></span>
<span class="line"><span>    host.rs</span></span>
<span class="line"><span>    stream.rs</span></span>
<span class="line"><span>    input.rs</span></span>
<span class="line"><span>  src/transport/</span></span>
<span class="line"><span>    mod.rs</span></span>
<span class="line"><span>    webrtc.rs</span></span>
<span class="line"><span>    websocket.rs</span></span>
<span class="line"><span>  src/media/</span></span>
<span class="line"><span>    video.rs</span></span>
<span class="line"><span>    audio.rs</span></span>
<span class="line"><span>  src/stats.rs</span></span></code></pre></div><p>第一阶段不是功能创新，而是“控制权迁移”：</p><ul><li>你自己的 crate</li><li>你自己的目录</li><li>你自己的构建脚本</li><li>你自己的 IPC 协议定义</li><li>你自己的模块边界</li><li>但底层先复用 moonlight-common</li></ul><p>成功标准：</p><ul><li>能编译</li><li>能启动</li><li>web-server 能 spawn 新 streamer</li><li>前端能完成 transport 协商</li><li>能走到 <code>ConnectionComplete</code></li></ul><hr><h2 id="_9-第二阶段-替换-web-server" tabindex="-1">9. 第二阶段：替换 web-server <a class="header-anchor" href="#_9-第二阶段-替换-web-server" aria-label="Permalink to &quot;9. 第二阶段：替换 web-server&quot;">​</a></h2><p>等自研 streamer 稳定后，再把 web-server 去掉或内嵌到 HomeSense：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>HomeSense server</span></span>
<span class="line"><span>  /moonlight/hosts</span></span>
<span class="line"><span>  /moonlight/apps</span></span>
<span class="line"><span>  /moonlight/pair</span></span>
<span class="line"><span>  /moonlight/stream</span></span>
<span class="line"><span>  spawn homesense-streamer</span></span></code></pre></div><p>这一步难度低，因为 web-server 只是业务壳。</p><hr><h2 id="_10-第三阶段-替换-moonlight-common-rust-的-rust-层" tabindex="-1">10. 第三阶段：替换 moonlight-common-rust 的 Rust 层 <a class="header-anchor" href="#_10-第三阶段-替换-moonlight-common-rust-的-rust-层" aria-label="Permalink to &quot;10. 第三阶段：替换 moonlight-common-rust 的 Rust 层&quot;">​</a></h2><p>可以先自己实现：</p><ul><li>serverinfo</li><li>applist</li><li>pair</li><li>launch</li><li>cancel</li><li>resume</li></ul><p>这些本质是 HTTP/HTTPS + XML/JSON + 证书签名。</p><p>这一步完成后，你就不需要 <code>MoonlightHost</code> 高级 API。</p><hr><h2 id="_11-第四阶段-替换-moonlight-common-c" tabindex="-1">11. 第四阶段：替换 moonlight-common-c <a class="header-anchor" href="#_11-第四阶段-替换-moonlight-common-c" aria-label="Permalink to &quot;11. 第四阶段：替换 moonlight-common-c&quot;">​</a></h2><p>这是最终核心：</p><ul><li>RTSP session</li><li>control stream</li><li>video stream</li><li>audio stream</li><li>input stream</li><li>FEC</li><li>ENet</li><li>RTP packet queue</li><li>crypto</li></ul><p>这一步不能一口吃。建议顺序：</p><ol><li>输入通道</li><li>RTSP/control</li><li>audio</li><li>video depacketizer</li><li>FEC/retransmit</li></ol><p>每替一个模块，都必须保留旧 C core 作为对照测试。</p><hr><h2 id="_12-当前最应该做的下一步" tabindex="-1">12. 当前最应该做的下一步 <a class="header-anchor" href="#_12-当前最应该做的下一步" aria-label="Permalink to &quot;12. 当前最应该做的下一步&quot;">​</a></h2><p>下一步不要继续改原来的 <code>streamer/src/main.rs</code>。</p><p>应该新建自己的 crate：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>D:\\files\\HomeSense-Studio-v2\\packages\\moonlight-streamer</span></span></code></pre></div><p>先做“兼容 streamer 壳”：</p><ol><li>复制 <code>common</code> 里的 IPC 类型或在 HomeSense 里定义等价类型</li><li>新 streamer 接收 <code>ServerIpcMessage::Init</code></li><li>新 streamer 返回 DebugLog / Setup</li><li>先不连真实 Moonlight，做 mock transport 协商</li><li>再接入 moonlight-common</li><li>最后替换 HomeSense 配置里的 streamer 路径</li></ol><p>这个路线最符合“自己造”：不是直接改上游，而是自己建立主工程，然后逐步吸收、替换、删除上游依赖。</p>`,104)])])}const m=e(n,[["render",l]]);export{k as __pageData,m as default};
